+
+export interface AuthFnAdminAuthorizationInput {
+  operationId: string;
+  params?: Record<string, string>;
+  query?: Record<string, string | undefined>;
+  body?: unknown;
+}
+
+export type AuthFnAdminAuthorizationResult =
+  | boolean
+  | {
+      allowed: boolean;
+      actorId?: string;
+      metadata?: Record<string, unknown>;
+    };
