+  const config: AuthFnConfig = {
+    ...options.authFnConfig,
+    database: wrapWithSchema(options.authFnConfig.database, schema)
+  };
+  const runner = createPluginRunner(config);
+
+  return {
+    config,
+    hooks: runner.hooks,
+    authorize: options.authorize
+  };
